113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        String idempotencyKey = currentIdempotencyKey();
115	        if (idempotencyKey != null) {
116	            Integer existingId = this.createdByIdempotencyKey.get(idempotencyKey);
117	            if (existingId != null) {
118	                Owner existing = this.clinicService.findOwnerById(existingId);
119	                if (existing != null) {
120	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
121	                }
122	            }
123	        }
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
127	        this.clinicService.saveOwner(owner, sharesHousehold);
128	        if (idempotencyKey != null) {
129	            this.createdByIdempotencyKey.put(idempotencyKey, owner.getId());
130	        }
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
